  if (key === null) return { ...mockStorage };
  if (Array.isArray(key)) {
    const res: Record<string, any> = {};
    for (const k of key) {
      if (mockStorage[k]) res[k] = mockStorage[k];
    }
    return res;
  }
  return { ...mockStorage };
});

const mockSet = vi.fn(async (data: Record<string, any>) => {
