import { PRE_AUCTION_HAR } from '../Shared/constants';



const MAX_ENTRIES = 1000;
const MAX_POST_TEXT_LENGTH = 10000;
const MAX_ARRAY_ITEMS = 50;

let entries: IHarLogEntry[] = [];
let flushTimeout: ReturnType<typeof setTimeout> | null = null;
let idCounter = 1;

export interface IHarTimingBreakdown {
  blocked?: number;
  dns?: number;
  connect?: number;
  send?: number;
  wait?: number;
  receive?: number;
  ssl?: number;
}

export interface IInitiatorInfo {
  type: string;
  url?: string;
  lineNumber?: number;
  stack?: any;
}

export interface IHarLogEntry {
  id: string;
  url: string;
  host: string;
  pathname: string;
  method: string;
  status: number;
  statusText?: string;
  startedDateTime: number;
  time: number;

  resourceType?: string;
  mimeType?: string;
  queryString?: Array<{ name: string; value: string }>;
  requestHeaders?: Array<{ name: string; value: string }>;
  responseHeaders?: Array<{ name: string; value: string }>;
  requestCookies?: Array<{ name: string; value: string }>;
  responseCookies?: Array<{ name: string; value: string }>;
  redirectURL?: string;
  initiator?: IInitiatorInfo;
  postData?: {
    mimeType?: string;
    text?: string;
    params?: Array<{ name: string; value: string }>;
  };
  timings?: IHarTimingBreakdown;
  contentSize?: number;
  bodySize?: number;
}

export const hostOf = (url: string): string => {
  try {
    return new URL(url).hostname;
  } catch {
    return '';
  }
};

export const pathOf = (url: string): string => {
  try {
    return new URL(url).pathname;
  } catch {
    return '';
  }
};


export const isRecordableUrl = (url: string): boolean => /^https?:\/\

const truncate = (str?: string, maxLen = MAX_POST_TEXT_LENGTH): string | undefined => {
  if (typeof str !== 'string') return undefined;
  return str.length > maxLen ? str.slice(0, maxLen) + '... [truncated]' : str;
};

const sanitizeNameValuePairs = (arr?: any[]): Array<{ name: string; value: string }> | undefined => {
  if (!Array.isArray(arr) || arr.length === 0) return undefined;
  return arr.slice(0, MAX_ARRAY_ITEMS).map((item) => ({
    name: String(item?.name ?? '').slice(0, 150),
    value: String(item?.value ?? '').slice(0, 2000),
  }));
};

const extractQueryParams = (harEntry: any, url: string): Array<{ name: string; value: string }> | undefined => {
  const fromHar = sanitizeNameValuePairs(harEntry?.request?.queryString);
  if (fromHar && fromHar.length > 0) return fromHar;

  if (url) {
    try {
      const parsed = new URL(url);
      const params: Array<{ name: string; value: string }> = [];
      parsed.searchParams.forEach((val, key) => {
        if (params.length < MAX_ARRAY_ITEMS) {
          params.push({ name: key.slice(0, 150), value: val.slice(0, 2000) });
        }
      });
      return params.length > 0 ? params : undefined;
    } catch {
      return undefined;
    }
  }
  return undefined;
};

const extractPostData = (postData: any): IHarLogEntry['postData'] => {
  if (!postData) return undefined;
  return {
    mimeType: postData.mimeType,
    text: truncate(postData.text),
    params: sanitizeNameValuePairs(postData.params),
  };
};

const extractTimings = (timings: any): IHarTimingBreakdown | undefined => {
  if (!timings || typeof timings !== 'object') return undefined;
  return {
    blocked: typeof timings.blocked === 'number' ? Math.max(0, Math.round(timings.blocked * 10) / 10) : undefined,
    dns: typeof timings.dns === 'number' ? Math.max(0, Math.round(timings.dns * 10) / 10) : undefined,
    connect: typeof timings.connect === 'number' ? Math.max(0, Math.round(timings.connect * 10) / 10) : undefined,
    send: typeof timings.send === 'number' ? Math.max(0, Math.round(timings.send * 10) / 10) : undefined,
    wait: typeof timings.wait === 'number' ? Math.max(0, Math.round(timings.wait * 10) / 10) : undefined,
    receive: typeof timings.receive === 'number' ? Math.max(0, Math.round(timings.receive * 10) / 10) : undefined,
    ssl: typeof timings.ssl === 'number' ? Math.max(0, Math.round(timings.ssl * 10) / 10) : undefined,
  };
};

export const toLogEntry = (harEntry: any): IHarLogEntry => {
  const url = harEntry?.request?.url || '';
  const now = Date.now();
  const entryId = `req_${idCounter++}_${now}`;

  return {
    id: entryId,
    url,
    host: hostOf(url),
    pathname: pathOf(url),
    method: harEntry?.request?.method || 'GET',
    status: harEntry?.response?.status ?? 0,
    statusText: harEntry?.response?.statusText || '',
    startedDateTime: new Date(harEntry?.startedDateTime).getTime() || 0,
    time: Math.round((Number(harEntry?.time) || 0) * 100) / 100,
    resourceType: harEntry?._resourceType,
    mimeType: harEntry?.response?.content?.mimeType,
    queryString: extractQueryParams(harEntry, url),
    requestHeaders: sanitizeNameValuePairs(harEntry?.request?.headers),
    responseHeaders: sanitizeNameValuePairs(harEntry?.response?.headers),
    requestCookies: sanitizeNameValuePairs(harEntry?.request?.cookies),
    responseCookies: sanitizeNameValuePairs(harEntry?.response?.cookies),
    redirectURL: harEntry?.response?.redirectURL || undefined,
    initiator: harEntry?._initiator || undefined,
    postData: extractPostData(harEntry?.request?.postData),
    timings: extractTimings(harEntry?.timings),
    contentSize: harEntry?.response?.content?.size,
    bodySize: harEntry?.response?.bodySize,
  };
};

/** Batched so high-frequency network bursts do not cause redundant writes. */
const flush = () => {
  flushTimeout = null;
  chrome.storage.local.set({ [PRE_AUCTION_HAR]: JSON.stringify(entries) });
};

const scheduleFlush = () => {
  if (flushTimeout) return;
  flushTimeout = setTimeout(flush, 300);
};

const record = (harEntry: any) => {
  const entry = toLogEntry(harEntry);
  if (!isRecordableUrl(entry.url)) return;
  entries.push(entry);
  if (entries.length > MAX_ENTRIES) entries = entries.slice(-MAX_ENTRIES);
  scheduleFlush();
};

export const reset = () => {
  entries = [];
  idCounter = 1;
  chrome.storage.local.set({ [PRE_AUCTION_HAR]: JSON.stringify(entries) });
};

export const collectHarLog = () => {
  if (!chrome.devtools?.network?.onRequestFinished) return;
  reset();
  chrome.devtools.network.onRequestFinished.addListener(record);
  chrome.tabs?.onUpdated.addListener((tabId, info) => {
    if (info.status === 'loading') reset();
  });
};

import type { AdUnit, AdUnitBid, Bid, BidderRequest, Config, EventRecord, EventPayload, PrebidJS } from 'prebid.js';
import { POPUP_LOADED, EVENTS, PREBID_DETECTION_TIMEOUT_IFRAME, PREBID_DETECTION_TIMEOUT } from '../Shared/constants';
import { EventBus, detectIframe } from '../Shared/utils';

export type { AdUnit, AdUnitBid, Bid, BidderRequest, Config, EventRecord, EventPayload, PrebidJS };

export class Prebid {
  globalPbjs: PrebidJS = window.pbjs;
  namespace: string;
  frameId: string | null;
  lastTimeUpdateSentToContentScript: number = 0;
  updateTimeout: ReturnType<typeof setTimeout> | null = null;
  updateRateInterval: number = 2500;
  sendToContentScriptPending: boolean = false;
  events: any[] = [];
  eventsApi: boolean = typeof this.globalPbjs?.getEvents === 'function' || false;

  constructor(namespace: string, iframeId: string | null) {
    this.namespace = namespace;
    this.frameId = iframeId;
    this.globalPbjs = window[namespace as keyof Window];
    this.addEventListeners();
    this.throttle(this.sendDetailsToBackground);
  }

  addEventListeners = (): void => {
    const pushEvent = (eventType: string, args: any) => {
      if (this.events.length >= 500) {
        this.events.shift();
      }
      this.events.push({ eventType, args });
    };

    if (typeof this.globalPbjs.onEvent !== 'function') return;
    this.globalPbjs.onEvent('auctionInit', (auctionInitData) => {
      if (!this.eventsApi) {
        pushEvent('auctionInit', auctionInitData);
      }
      this.throttle(this.sendDetailsToBackground);
    });

    this.globalPbjs.onEvent('auctionEnd', (auctionEndData) => {
      if (!this.eventsApi) {
        pushEvent('auctionEnd', auctionEndData);
      }
      this.throttle(this.sendDetailsToBackground);
    });

    this.globalPbjs.onEvent('bidRequested', (bidRequestedData) => {
      if (!this.eventsApi) {
        pushEvent('bidRequested', bidRequestedData);
      }
      this.throttle(this.sendDetailsToBackground);
    });

    this.globalPbjs.onEvent('bidResponse', (bidResponseData) => {
      if (!this.eventsApi) {
        pushEvent('bidResponse', bidResponseData);
      }
      this.throttle(this.sendDetailsToBackground);
    });

    this.globalPbjs.onEvent('noBid', (noBidData) => {
      if (!this.eventsApi) {
        pushEvent('noBid', noBidData);
      }
      this.throttle(this.sendDetailsToBackground);
    });

    this.globalPbjs.onEvent('bidWon', (bidWonData) => {
      if (!this.eventsApi) {
        pushEvent('bidWon', bidWonData);
      }
      this.throttle(this.sendDetailsToBackground);
    });

    window.addEventListener(
      'message',
      (event) => {
        if (event.source !== window || event.origin !== window.origin) return;
        if (!event.data.profPrebid) return;
        if (event.data.type === POPUP_LOADED) {
          this.sendDetailsToBackground();
        }
      },
      false
    );
  };

  getDebugConfig = () => {
    const pbjsDebugString = window.sessionStorage.getItem('pbjs:debugging');
    try {
      return JSON.parse(pbjsDebugString);
    } catch (e) {
      console.error(e);
    }
  };

  getEventsObjUrl = () => {
    const events = this.globalPbjs?.getEvents ? this.globalPbjs.getEvents() : this.events;

    const safeStringify = (obj: any): string => {
      const ancestors: any[] = [];
      return JSON.stringify(obj, function (key, value) {
        if (value instanceof Window || value instanceof Node || value instanceof HTMLElement) {
          return '[DOM Node]';
        }
        if (typeof value !== 'object' || value === null) {
          return value;
        }

        while (ancestors.length > 0 && ancestors[ancestors.length - 1] !== this) {
          ancestors.pop();
        }
        if (ancestors.includes(value)) {
          return '[Circular]';
        }
        ancestors.push(value);
        return value;
      });
    };

    const string = `[${events
      .map((event) => {
        let processedEvent = event;
        if (event?.eventType === 'adRenderSucceeded' && event?.args?.doc) {
          processedEvent = {
            ...event,
            args: {
              ...event.args,
              doc: 'pruned by Prof. Prebid',
            },
          };
        }
        try {
          return safeStringify(processedEvent);
        } catch (error) {
          return JSON.stringify({
            eventType: event.eventType,
            args: { error: 'Prof. Prebid could not stringify this event.' },
            elapsedTime: event.elapsedTime,
          });
        }
      })
      .join()}]`;

    if (string === '[]') return null;
    const blob = new Blob([string], { type: 'application/json' });
    const objectURL = URL.createObjectURL(blob);
    return objectURL;
  };

  sendDetailsToBackground = (): void => {
    this.globalPbjs.que.push(async () => {
      const eventsUrl = this.getEventsObjUrl();
      if (!eventsUrl) return;
      const config = this.globalPbjs.getConfig();
      const eids = this.globalPbjs.getUserIdsAsEids ? this.globalPbjs.getUserIdsAsEids() : [];
      const timeout = window.PREBID_TIMEOUT || null;
      const prebidDetail: IPrebidDetails = {
        config,
        debug: this.getDebugConfig(),
        eids,
        events: [],
        eventsUrl,
        namespace: this.namespace,
        frameId: this.frameId,
        installedModules: this.globalPbjs.installedModules,
        timeout,
        version: this.globalPbjs.version,
        bidderSettings: this.globalPbjs.bidderSettings,
      };
      EventBus.emit(EVENTS.SEND_PREBID_DETAILS_TO_BACKGROUND, prebidDetail);
      this.sendToContentScriptPending = false;
    });
  };

  throttle = (fn: () => void) => {
    const now = Date.now();

    // First call: fire immediately
    if (!this.lastTimeUpdateSentToContentScript) {
      this.lastTimeUpdateSentToContentScript = now;
      fn();
      return;
    }

    const elapsed = now - this.lastTimeUpdateSentToContentScript;
    const remaining = this.updateRateInterval - elapsed;

    if (remaining <= 0) {
      // Window passed: run immediately and clear any pending trailing call
      if (this.updateTimeout) {
        clearTimeout(this.updateTimeout);
        this.updateTimeout = null;
      }
      this.lastTimeUpdateSentToContentScript = now;
      fn();
    } else if (!this.updateTimeout) {
      // Schedule a trailing call if not already scheduled
      this.updateTimeout = setTimeout(() => {
        this.lastTimeUpdateSentToContentScript = Date.now();
        this.updateTimeout = null;
        fn();
      }, remaining);
    }
  };
}

export const addEventListenersForPrebid = (frameId: string) => {
  const allreadyInjectedPrebid: string[] = [];

  const inject = (global: string) => {
    if (!allreadyInjectedPrebid.includes(global)) {
      new Prebid(global, frameId);
      allreadyInjectedPrebid.push(global);
    }
  };

  const checkGlobals = (globals: string[]) => {
    if (globals && Array.isArray(globals)) {
      globals.forEach(inject);
    }
  };

  // Check immediately
  if (window._pbjsGlobals) {
    checkGlobals(window._pbjsGlobals);
  }

  // Intercept future assignments
  let _pbjsGlobals: string[] = window._pbjsGlobals || [];
  try {
    Object.defineProperty(window, '_pbjsGlobals', {
      get: () => _pbjsGlobals,
      set: (val: string[]) => {
        _pbjsGlobals = val;
        checkGlobals(val);
      },
      configurable: true,
      enumerable: true,
    });
  } catch (e) {
    // Fallback if defineProperty fails (e.g. non-configurable already)
    const interval = setInterval(() => {
      if (window._pbjsGlobals) {
        checkGlobals(window._pbjsGlobals);
        clearInterval(interval);
      }
    }, 1000);
    setTimeout(() => clearInterval(interval), 10000);
  }
};

