  const mockNoBids = [
    {
      bidder: 'appnexus',
      adUnitCode: 'slot-1-very-long-name-exceeding-thirty-characters',
      timeToRespond: 200,
    },
  ];

  const mockAuctionEvents: any = [
    {
      args: {
        bidsReceived: mockReceivedBids,
        noBids: mockNoBids,
