      { name: 'gdpr', value: '1' },
      { name: 'gdpr_consent', value: 'CP12345' },
      { name: 'nested', value: 'https%3A%2F%2Fexample.com%2Fcb' },
    ],
    requestHeaders: [{ name: 'Content-Type', value: 'application/json' }],
    responseHeaders: [{ name: 'Cache-Control', value: 'no-store' }],
