describe('StateContextProvider', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  it('uses default fallback values when consumer rendered outside provider', () => {
    render(<TestChild />);
    expect(screen.getByTestId('frameId').textContent).toBe('');
    expect(screen.getByTestId('pbjsNamespace').textContent).toBe('');
  });

  it('sets default frameId to top-window when top-window prebids exist and processes all event types', async () => {
    const mockInspectedContext: any = {
      frames: {
        'top-window': {
          prebids: {
            pbjs: {
              events: [
                { eventType: 'auctionInit', args: { timestamp: 200, adUnitCodes: ['code2'] } },
                { eventType: 'auctionInit', args: { timestamp: 100, adUnitCodes: ['code1'] } },
                { eventType: 'bidResponse', args: { bidder: 'appnexus' } },
                { eventType: 'bidRequested', args: {} },
                { eventType: 'noBid', args: { bidder: 'rubicon' } },
                { eventType: 'bidderDone', args: {} },
                { eventType: 'bidWon', args: {} },
                { eventType: 'auctionEnd', args: {} },
                { eventType: 'adRenderSucceeded', args: {} },
              ],
            },
            tcf: { version: 2 },
          },
          googleAdManager: { slots: [] },
        },
      },
      downloading: 'false',
      syncState: '',
      initReqChainResult: {},
    };

    render(
      <InspectedPageContext.Provider value={mockInspectedContext}>
        <StateContextProvider>
          <TestChild />
        </StateContextProvider>
      </InspectedPageContext.Provider>
    );

    expect(screen.getByTestId('frameId').textContent).toBe('top-window');
    expect(screen.getByTestId('pbjsNamespace').textContent).toBe('pbjs');
    expect(screen.getByTestId('eventsCount').textContent).toBe('9');
    expect(screen.getByTestId('adUnitCodes').textContent).toBe('code2,code1');
    expect(screen.getByTestId('bidders').textContent).toBe('appnexus,rubicon');
    expect(screen.getByTestId('auctionInit').textContent).toBe('100,200');
    expect(screen.getByTestId('bidRequested').textContent).toBe('1');
    expect(screen.getByTestId('noBid').textContent).toBe('1');
    expect(screen.getByTestId('bidderDone').textContent).toBe('1');
    expect(screen.getByTestId('winningBids').textContent).toBe('1');
    expect(screen.getByTestId('auctionEnd').textContent).toBe('1');
    expect(screen.getByTestId('adsRendered').textContent).toBe('1');
  });

  it('sets default frameId to first frame with prebids if top-window has no prebids', async () => {
    const mockInspectedContext: any = {
      frames: {
        'top-window': {},
        'frame-1': {
          prebids: {
            otherPbjs: {
              events: [],
            },
          },
        },
      },
    };

    render(
      <InspectedPageContext.Provider value={mockInspectedContext}>
        <StateContextProvider>
          <TestChild />
        </StateContextProvider>
      </InspectedPageContext.Provider>
    );

    expect(screen.getByTestId('frameId').textContent).toBe('frame-1');
    expect(screen.getByTestId('pbjsNamespace').textContent).toBe('otherPbjs');
  });

  it('defaults to top-window if no frames have prebids', async () => {
    const mockInspectedContext: any = {
      frames: {
        'top-window': {},
      },
    };

    render(
      <InspectedPageContext.Provider value={mockInspectedContext}>
        <StateContextProvider>
          <TestChild />
        </StateContextProvider>
      </InspectedPageContext.Provider>
    );

    expect(screen.getByTestId('frameId').textContent).toBe('top-window');
  });

  it('allows changing frameId, namespace, and state setters', async () => {
    const mockInspectedContext: any = {
      frames: {
        'top-window': { prebids: { pbjs: { events: [] } } },
        'frame-2': { prebids: { customPbjs: { events: [] } } },
      },
    };

    render(
      <InspectedPageContext.Provider value={mockInspectedContext}>
        <StateContextProvider>
          <TestChild />
        </StateContextProvider>
      </InspectedPageContext.Provider>
    );

    act(() => {
      screen.getByText('Change Frame').click();
    });

    expect(screen.getByTestId('frameId').textContent).toBe('frame-2');

    act(() => {
      screen.getByText('Change Namespace').click();
    });

    expect(screen.getByTestId('pbjsNamespace').textContent).toBe('customPbjs');

    act(() => {
      screen.getByText('Set Initiator').click();
      screen.getByText('Set Refresh').click();
      screen.getByText('Set Init Data').click();
      screen.getByText('Set Release Info').click();
      screen.getByText('Set Topics').click();
    });

    expect(screen.getByTestId('isRefresh').textContent).toBe('true');
    expect(screen.getByTestId('initDataLoaded').textContent).toBe('true');
    expect(screen.getByTestId('topics').textContent).toBe('topicA');
  });

  it('fetches browsingTopics when supported by document', async () => {
    const mockBrowsingTopics = vi.fn().mockResolvedValue(['sports', 'news']);
    const originalFeaturePolicy = document.featurePolicy;
    const originalBrowsingTopics = document.browsingTopics;

    (document as any).featurePolicy = {
      allowsFeature: (feature: string) => feature === 'browsing-topics',
    };
    (document as any).browsingTopics = mockBrowsingTopics;

    const mockInspectedContext: any = {
      frames: {
        'top-window': { prebids: { pbjs: { events: [] } } },
      },
    };

    await act(async () => {
      render(
        <InspectedPageContext.Provider value={mockInspectedContext}>
          <StateContextProvider>
            <TestChild />
          </StateContextProvider>
        </InspectedPageContext.Provider>
      );
    });

    expect(mockBrowsingTopics).toHaveBeenCalled();
    expect(screen.getByTestId('topics').textContent).toBe('sports,news');

    (document as any).featurePolicy = originalFeaturePolicy;
    (document as any).browsingTopics = originalBrowsingTopics;
  });

  it('handles browsingTopics failure gracefully', async () => {
    const consoleSpy = vi.spyOn(console, 'error').mockImplementation(() => {});
    const mockBrowsingTopics = vi.fn().mockRejectedValue(new Error('Topics permission error'));
    const originalFeaturePolicy = document.featurePolicy;
    const originalBrowsingTopics = document.browsingTopics;

    (document as any).featurePolicy = {
      allowsFeature: (feature: string) => feature === 'browsing-topics',
    };
    (document as any).browsingTopics = mockBrowsingTopics;

    const mockInspectedContext: any = {
      frames: {
        'top-window': { prebids: { pbjs: { events: [] } } },
      },
    };

    await act(async () => {
      render(
        <InspectedPageContext.Provider value={mockInspectedContext}>
          <StateContextProvider>
            <TestChild />
          </StateContextProvider>
        </InspectedPageContext.Provider>
      );
    });

    expect(consoleSpy).toHaveBeenCalledWith('Error fetching topics', expect.any(Error));

    consoleSpy.mockRestore();
    (document as any).featurePolicy = originalFeaturePolicy;
    (document as any).browsingTopics = originalBrowsingTopics;
  });
});

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { fetchEvents } from './fetchEvents';
import { DOWNLOAD_FAILED } from '../constants';
import { sendChromeTabsMessage } from '../../Shared/utils';

vi.mock('../../Shared/utils', () => ({
  getTabId: vi.fn(),
  sendChromeTabsMessage: vi.fn(),
}));

describe('fetchEvents', () => {
  const setDownloading = vi.fn();
  const setSyncInfo = vi.fn();

  beforeEach(() => {
    vi.clearAllMocks();
    global.chrome = {
      tabs: {
        query: vi.fn((queryInfo, cb) => cb([{ url: 'https://example.com/page' }])),
      },
      windows: {
        WINDOW_ID_CURRENT: 1,
      },
    } as any;
  });

  it('returns empty object when tabInfo is null or undefined', async () => {
    expect(await fetchEvents(null as any, setDownloading, setSyncInfo, [])).toEqual({});
    expect(await fetchEvents(undefined as any, setDownloading, setSyncInfo, [])).toEqual({});
  });

  it('skips frame if frame has no prebids', async () => {
    const tabInfo: any = {
      'top-window': {},
    };
    const result = await fetchEvents(tabInfo, setDownloading, setSyncInfo, []);
    expect(result).toEqual({ 'top-window': {} });
    expect(setDownloading).not.toHaveBeenCalled();
  });

  it('successfully fetches events for top-window', async () => {
    const tabInfo: any = {
      'top-window': {
        prebids: {
          pbjs: {
            eventsUrl: 'https://example.com/events.json',
          },
        },
      },
    };

    const mockEvents = [{ eventName: 'bidResponse' }];
    global.fetch = vi.fn().mockResolvedValue({
      json: vi.fn().mockResolvedValue(mockEvents),
    });

    const result = await fetchEvents(tabInfo, setDownloading, setSyncInfo, []);
    expect(result['top-window'].prebids.pbjs.events).toEqual(mockEvents);
    expect(setDownloading).toHaveBeenCalledWith('true');
    expect(setDownloading).toHaveBeenCalledWith('false');
    expect(setSyncInfo).toHaveBeenCalledWith(null);
  });

  it('handles non-top-window frameId domain matching', async () => {
    const tabInfo: any = {
      'https://sub.example.com/iframe.html': {
        prebids: {
          pbjs: {
            eventsUrl: 'https://sub.example.com/events.json',
          },
        },
      },
    };

    const mockEvents = [{ eventName: 'bidWon' }];
    global.fetch = vi.fn().mockResolvedValue({
      json: vi.fn().mockResolvedValue(mockEvents),
    });

    const result = await fetchEvents(tabInfo, setDownloading, setSyncInfo, []);
    expect(result['https://sub.example.com/iframe.html'].prebids.pbjs.events).toEqual(mockEvents);
  });

  it('skips when hostname does not match current tab URL host', async () => {
    const tabInfo: any = {
      'top-window': {
        prebids: {
          pbjs: {
            eventsUrl: 'https://otherdomain.com/events.json',
          },
        },
      },
    };

    const result = await fetchEvents(tabInfo, setDownloading, setSyncInfo, []);
    expect(setDownloading).not.toHaveBeenCalled();
  });

  it('skips download if url is already in downloadingUrls array', async () => {
    const eventsUrl = 'https://example.com/events.json';
    const tabInfo: any = {
      'top-window': {
        prebids: {
          pbjs: {
            eventsUrl,
          },
        },
      },
    };

    const downloadingUrls: any = [eventsUrl];
    downloadingUrls[eventsUrl] = true;

    const result = await fetchEvents(tabInfo, setDownloading, setSyncInfo, downloadingUrls);
    expect(global.fetch).not.toHaveBeenCalled();
  });

  it('handles download failure gracefully and removes frame when no prebids remain', async () => {
    const tabInfo: any = {
      'top-window': {
        prebids: {
          pbjs: {
            eventsUrl: 'https://example.com/events.json',
          },
        },
      },
    };

    global.fetch = vi.fn().mockRejectedValue(new Error('Network error'));

    const result = await fetchEvents(tabInfo, setDownloading, setSyncInfo, []);
    expect(sendChromeTabsMessage).toHaveBeenCalledWith(DOWNLOAD_FAILED, { eventsUrl: 'https://example.com/events.json' });
    expect(setDownloading).toHaveBeenCalledWith('error');
    expect(result['top-window']).toBeUndefined();
  });

  it('keeps frame if other prebid namespaces remain after download error', async () => {
    const tabInfo: any = {
      'top-window': {
        prebids: {
          failingPbjs: {
            eventsUrl: 'https://example.com/failing.json',
          },
          workingPbjs: {
            eventsUrl: 'https://otherdomain.com/working.json',
          },
        },
      },
    };

    global.fetch = vi.fn().mockRejectedValue(new Error('Network error'));

    const result = await fetchEvents(tabInfo, setDownloading, setSyncInfo, []);
    expect(result['top-window']).toBeDefined();
    expect(result['top-window'].prebids.failingPbjs).toBeUndefined();
    expect(result['top-window'].prebids.workingPbjs).toBeDefined();
  });

  it('handles invalid URLs safely in safelyConstructURL and getCurrentTabURL', async () => {
    global.chrome = {
      tabs: {
        query: vi.fn((queryInfo, cb) => cb([{}])),
      },
      windows: {
        WINDOW_ID_CURRENT: 1,
      },
    } as any;

    const tabInfo: any = {
      'top-window': {
        prebids: {
          pbjs: {
            eventsUrl: 'invalid-url-string',
          },
        },
      },
    };

    global.fetch = vi.fn().mockRejectedValue(new Error('Invalid URL'));

    const result = await fetchEvents(tabInfo, setDownloading, setSyncInfo, []);
    expect(setDownloading).toHaveBeenCalledWith('true');
    expect(setDownloading).toHaveBeenCalledWith('error');
  });
});

import { getTabId, sendChromeTabsMessage } from '../../Shared/utils';
import { DOWNLOAD_FAILED } from '../constants';

const safelyConstructURL = (url: string) => {
  try {
    const urlObj = new URL(url.replace('blob:', ''));
    return urlObj;
  } catch (error) {
    return {} as URL;
  }
};

const getCurrentTabURL = async (): Promise<URL> => {
  return new Promise((resolve) => {
    chrome.tabs.query(
      {
        active: true,
        windowId: chrome.windows.WINDOW_ID_CURRENT,
      },
      (tabs) => {
        const activeTab = tabs[0];
        const urlObj = safelyConstructURL(activeTab?.url);
        resolve(urlObj);
      }
    );
  });
};

export const fetchEvents = async (tabInfo: IFrameInfos, setDownloading: React.Dispatch<React.SetStateAction<'true' | 'false' | 'error'>>, setSyncInfo: React.Dispatch<React.SetStateAction<string | null>>, downloadingUrls: string[]) => {
  if (!tabInfo) return {};

  for (const frameId of Object.keys(tabInfo)) {
    const { prebids } = tabInfo[frameId];
    if (!prebids) continue;
    for (const [namespace, prebid] of Object.entries(prebids)) {
      const { hostname: eventsURLHost } = safelyConstructURL(prebid.eventsUrl);
      const { hostname: currentTabURLHost } = frameId === 'top-window' ? await getCurrentTabURL() : safelyConstructURL(frameId);
      if (eventsURLHost !== currentTabURLHost) continue;

      setSyncInfo(`try to download Events from ${prebid.eventsUrl}`);
      setDownloading('true');
      try {
        if (prebid && prebid.eventsUrl in downloadingUrls) {
          // skip download if already downloading or from another domain or prebid is undefined
        } else {
          setSyncInfo(`${namespace}: downloading ${prebid.eventsUrl}`);
          const response = await fetch(prebid.eventsUrl);
          setSyncInfo(`${namespace}: get JSON from response stream`);
          prebid.events = prebid.events || [];
          prebid.events = await response.json();
          setDownloading('false');
          setSyncInfo(null);
        }
      } catch (error) {
        sendChromeTabsMessage(DOWNLOAD_FAILED, { eventsUrl: prebid.eventsUrl });
        setSyncInfo(`${namespace}: error during download of ${prebid.eventsUrl}`);
        setDownloading('error');
        delete tabInfo[frameId].prebids[namespace];
        if (Object.keys(tabInfo[frameId].prebids).length === 0) {
          delete tabInfo[frameId];
        }
      }
    }
  }
  return { ...tabInfo };
};

import React from 'react';
import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { renderHook, act } from '@testing-library/react';
import { useDebounce } from './useDebounce';

describe('useDebounce', () => {
  beforeEach(() => {
    vi.useFakeTimers();
  });

  afterEach(() => {
    vi.useRealTimers();
  });

  it('returns initial value immediately', () => {
    const { result } = renderHook(() => useDebounce('hello', 500));
    expect(result.current).toBe('hello');
  });

  it('updates value after delay', async () => {
    let value = 'initial';
    const { result, rerender } = renderHook(() => useDebounce(value, 500));

    expect(result.current).toBe('initial');

    value = 'updated';
    rerender();

    expect(result.current).toBe('initial');

    act(() => {
      vi.advanceTimersByTime(600);
    });

    expect(result.current).toBe('updated');
  });

  it('resets timer on rapid value changes', () => {
    let value = 'a';
    const { result, rerender } = renderHook(() => useDebounce(value, 500));

    value = 'b';
    rerender();
    act(() => {
      vi.advanceTimersByTime(200);
    });

    value = 'c';
    rerender();
    act(() => {
      vi.advanceTimersByTime(200);
    });

    expect(result.current).toBe('a');

    act(() => {
      vi.advanceTimersByTime(500);
    });
    expect(result.current).toBe('c');
  });
});

import { IPrebidConfig, IPrebidConfigPriceBucket } from '../../../Injected/prebid';

const _defaultPrecision = 2;
const _lgPriceConfig = {
  buckets: [
    {
      max: 5,
      increment: 0.5,
    },
  ],
};

const _mgPriceConfig = {
  buckets: [
    {
      max: 20,
      increment: 0.1,
    },
  ],
};

const _hgPriceConfig = {
  buckets: [
    {
      max: 20,
      increment: 0.01,
    },
  ],
};

const _densePriceConfig = {
  buckets: [
    {
      max: 3,
      increment: 0.01,
    },
    {
      max: 8,
      increment: 0.05,
    },
    {
      max: 20,
      increment: 0.5,
    },
  ],
};

const _autoPriceConfig = {
  buckets: [
    {
      max: 5,
      increment: 0.05,
    },
    {
      max: 10,
      increment: 0.1,
    },
    {
      max: 20,
      increment: 0.5,
    },
  ],
};

const isEmpty = (o: Object) => {
  if (JSON.stringify(o) === '{}' || JSON.stringify(o) === '[]') {
    return true;
  }
  return false;
};

const getPriceBucketString = (cpm: string, customConfig: IPrebidConfigPriceBucket, granularityMultiplier: number = 1): { low: string; med: string; high: string; auto: string; dense: string; custom: string } => {
  let cpmFloat: number = parseFloat(cpm);
  if (isNaN(cpmFloat)) {
    cpmFloat = NaN;
  }

  return {
    low: cpmFloat.toString() === '' ? '' : getCpmStringValue(cpm, _lgPriceConfig, granularityMultiplier),
    med: cpmFloat.toString() === '' ? '' : getCpmStringValue(cpm, _mgPriceConfig, granularityMultiplier),
    high: cpmFloat.toString() === '' ? '' : getCpmStringValue(cpm, _hgPriceConfig, granularityMultiplier),
    auto: cpmFloat.toString() === '' ? '' : getCpmStringValue(cpm, _autoPriceConfig, granularityMultiplier),
    dense: cpmFloat.toString() === '' ? '' : getCpmStringValue(cpm, _densePriceConfig, granularityMultiplier),
    custom: cpmFloat.toString() === '' ? '' : getCpmStringValue(cpm, customConfig, granularityMultiplier),
  };
};

const getCpmStringValue = (cpm: string, config: any, granularityMultiplier: number): string => {
  let cpmStr = '';
  if (!isValidPriceConfig(config)) {
    return cpmStr;
  }
  const cap = config.buckets.reduce(
    (prev: IPrebidConfigPriceBucket, curr: IPrebidConfigPriceBucket) => {
      if (prev.max > curr.max) {
        return prev;
      }
      return curr;
    },
    {
      max: 0,
    } as IPrebidConfigPriceBucket
  );

  let bucketFloor = 0;
  let bucket = config.buckets.find((bucket: IPrebidConfigPriceBucket) => {
    if (Number(cpm) > cap.max * granularityMultiplier) {
      let precision = bucket.precision;
      if (typeof precision === 'undefined') {
        precision = _defaultPrecision;
      }
      cpmStr = (bucket.max * granularityMultiplier).toFixed(precision);
    } else if (Number(cpm) <= bucket.max * granularityMultiplier && Number(cpm) >= bucketFloor * granularityMultiplier) {
      bucket.min = bucketFloor;
      return bucket;
    } else {
      bucketFloor = bucket.max;
    }
  });
  if (bucket) {
    cpmStr = getCpmTarget(cpm, bucket, granularityMultiplier);
  }
  return cpmStr;
};

const isValidPriceConfig = (config: IPrebidConfig['customPriceBucket']) => {
  if (isEmpty(config) || !config.buckets || !Array.isArray(config.buckets)) {
    return false;
  }
  let isValid = true;
  config.buckets.forEach((bucket) => {
    if (!bucket.max || !bucket.increment) {
      isValid = false;
    }
  });
  return isValid;
};

const getCpmTarget = (cpm: string, bucket: IPrebidConfigPriceBucket, granularityMultiplier: number) => {
  const precision = typeof bucket.precision !== 'undefined' ? bucket.precision : _defaultPrecision;
  const increment = bucket.increment * granularityMultiplier;
  const bucketMin = bucket.min * granularityMultiplier;
  let roundingFunction = Math.floor;

  let pow = Math.pow(10, precision + 2);
  let cpmToRound = (Number(cpm) * pow - bucketMin * pow) / (increment * pow);
  let cpmTarget;
  let invalidRounding;

  try {
    cpmTarget = roundingFunction(cpmToRound) * increment + bucketMin;
  } catch (err) {
    invalidRounding = true;
  }
  if (invalidRounding || typeof cpmTarget !== 'number') {
    cpmTarget = Math.floor(cpmToRound) * increment + bucketMin;
  }

  cpmTarget = Number(cpmTarget.toFixed(10));
  return cpmTarget.toFixed(precision);
};

export { getPriceBucketString, isValidPriceConfig };

export interface PrebidGroundTruth {
  namespace: string;
  version: string | null;
  installedModules: string[];
  config: Record<string, any> | null;
  bidderSettings?: Record<string, any> | null;
  eids: any[];
  adUnits: any[];
  events: Array<{ eventType: string; args: any; elapsedTime?: number }>;
  winningBids: any[];
  timeoutSetting?: number | null;
}

export interface ExtensionCapturedState {
  namespace: string;
  version?: string;
  installedModules?: string[];
  config?: Record<string, any>;
  bidderSettings?: Record<string, any>;
  eids?: any[];
  events?: Array<{ eventType: string; args: any; elapsedTime?: number }>;
  eventsCount?: number;
  eventsUrl?: string | null;
  mcpSnapshot?: any;
}

export interface DomainAuditResult {
  domain: string;
  passed: boolean;
  score: number;
  summary: string;
  details: {
    expected?: any;
    actual?: any;
    missing?: any;
    discrepancies?: string[];
  };
}

export interface SurfaceAuditReport {
  timestamp: string;
  targetUrl: string;
  overallPassed: boolean;
  namespace: string;
  domains: {
    version: DomainAuditResult;
    modules: DomainAuditResult;
    config: DomainAuditResult;
    events: DomainAuditResult;
    userIds: DomainAuditResult;
    bids: DomainAuditResult;
    adUnits: DomainAuditResult;
  };
}

export function sanitizeForComparison(val: any): any {
  if (val === null || val === undefined) return val;
  if (typeof val === 'function') return '[Function]';
  if (typeof val !== 'object') return val;
  if (Array.isArray(val)) {
    return val.map(sanitizeForComparison);
  }
  const clean: Record<string, any> = {};
  const sortedKeys = Object.keys(val).sort();
  for (const k of sortedKeys) {
    if (k.startsWith('_') && typeof val[k] === 'function') continue;
    clean[k] = sanitizeForComparison(val[k]);
  }
  return clean;
}

export function reconcilePrebidSurface(truth: PrebidGroundTruth, captured: ExtensionCapturedState, targetUrl: string = 'synthetic'): SurfaceAuditReport {
  const versionPassed = truth.version ? truth.version === captured.version : true;
  const versionResult: DomainAuditResult = {
    domain: 'Version',
    passed: versionPassed,
    score: versionPassed ? 100 : 0,
    summary: versionPassed ? `Prebid version ${truth.version} matched exactly.` : `Version mismatch: Expected ${truth.version}, Extension captured ${captured.version}`,
    details: { expected: truth.version, actual: captured.version },
  };

  // 2. Installed Modules Reconcile
  const truthModules = new Set(truth.installedModules || []);
  const capturedModules = new Set(captured.installedModules || []);
  const missingModules = [...truthModules].filter((m) => !capturedModules.has(m));
  const modulesPassed = missingModules.length === 0;
  const modulesScore = truthModules.size > 0 ? Math.round(((truthModules.size - missingModules.length) / truthModules.size) * 100) : 100;
  const modulesResult: DomainAuditResult = {
    domain: 'Installed Modules',
    passed: modulesPassed,
    score: modulesScore,
    summary: modulesPassed ? `All ${truthModules.size} installed modules detected.` : `Missing ${missingModules.length} modules: ${missingModules.join(', ')}`,
    details: {
      expected: [...truthModules],
      actual: [...capturedModules],
      missing: missingModules,
    },
  };

  // 3. Config Reconcile
  const truthConfig = truth.config || {};
  const capturedConfig = captured.config || {};
  const truthConfigKeys = Object.keys(truthConfig);
  const missingConfigKeys = truthConfigKeys.filter((k) => !(k in capturedConfig));
  const valueMismatches: string[] = [];

  for (const key of truthConfigKeys) {
    if (key in capturedConfig) {
      const expVal = JSON.stringify(sanitizeForComparison(truthConfig[key]));
      const actVal = JSON.stringify(sanitizeForComparison(capturedConfig[key]));
      if (expVal !== actVal) {
        // Deep compare check
        valueMismatches.push(key);
      }
    }
  }

  const configPassed = missingConfigKeys.length === 0 && valueMismatches.length === 0;
  const configScore = truthConfigKeys.length > 0 ? Math.round(((truthConfigKeys.length - missingConfigKeys.length - valueMismatches.length) / truthConfigKeys.length) * 100) : 100;
  const configResult: DomainAuditResult = {
    domain: 'Configuration (pbjs.getConfig)',
    passed: configPassed,
    score: Math.max(0, configScore),
    summary: configPassed ? `All ${truthConfigKeys.length} config sections correctly surfaced.` : `Config discrepancies: missing [${missingConfigKeys.join(', ')}], mismatched values [${valueMismatches.join(', ')}]`,
    details: {
      missing: missingConfigKeys,
      discrepancies: valueMismatches,
    },
  };

  // 4. Events Reconcile
  const truthEvents = truth.events || [];
  const capturedEvents = captured.events || [];
  const truthTypes = truthEvents.map((e) => e.eventType);
  const capturedTypes = capturedEvents.map((e) => e.eventType);

  const eventCountsTruth: Record<string, number> = {};
  const eventCountsCaptured: Record<string, number> = {};
  truthTypes.forEach((t) => (eventCountsTruth[t] = (eventCountsTruth[t] || 0) + 1));
  capturedTypes.forEach((t) => (eventCountsCaptured[t] = (eventCountsCaptured[t] || 0) + 1));

  const missingEventTypes: string[] = [];
  const countMismatches: string[] = [];
  for (const [type, count] of Object.entries(eventCountsTruth)) {
    const capCount = eventCountsCaptured[type] || 0;
    if (capCount === 0) {
      missingEventTypes.push(type);
    } else if (capCount < count) {
      countMismatches.push(`${type} (expected ${count}, got ${capCount})`);
    }
  }

  const eventsPassed = missingEventTypes.length === 0 && countMismatches.length === 0;
  const eventsScore = truthEvents.length > 0 ? Math.round(((truthEvents.length - missingEventTypes.length - countMismatches.length) / Math.max(1, truthEvents.length)) * 100) : 100;
  const eventsResult: DomainAuditResult = {
    domain: 'Events Stream (pbjs.getEvents)',
    passed: eventsPassed,
    score: Math.max(0, Math.min(100, eventsScore)),
    summary: eventsPassed ? `All ${truthEvents.length} events across ${Object.keys(eventCountsTruth).length} event types surfaced.` : `Missing event types: [${missingEventTypes.join(', ')}]; count discrepancies: [${countMismatches.join(', ')}]`,
    details: {
      expected: eventCountsTruth,
      actual: eventCountsCaptured,
      missing: missingEventTypes,
      discrepancies: countMismatches,
    },
  };

  // 5. User IDs (EIDs) Reconcile
  const truthEids = truth.eids || [];
  const capturedEids = captured.eids || [];
  const truthSources = truthEids.map((e: any) => e.source).filter(Boolean);
  const capturedSources = capturedEids.map((e: any) => e.source).filter(Boolean);
  const missingSources = truthSources.filter((s: string) => !capturedSources.includes(s));
  const userIdsPassed = missingSources.length === 0;
  const userIdsScore = truthSources.length > 0 ? Math.round(((truthSources.length - missingSources.length) / truthSources.length) * 100) : 100;
  const userIdsResult: DomainAuditResult = {
    domain: 'User IDs & EIDs',
    passed: userIdsPassed,
    score: userIdsScore,
    summary: userIdsPassed ? `All ${truthSources.length} EID sources surfaced (${truthSources.join(', ') || 'none'}).` : `Missing EID sources: ${missingSources.join(', ')}`,
    details: {
      expected: truthSources,
      actual: capturedSources,
      missing: missingSources,
    },
  };

  // 6. Bids / Winning Bids
  const truthWinning = truth.winningBids || [];
  const capturedWinning = captured.mcpSnapshot?.winningBids || [];
  const truthWinners = truthWinning.map((b: any) => b.bidder || b.bidderCode);
  const capturedWinners = capturedWinning.map((b: any) => b.bidder || b.bidderCode);
  const bidsPassed = truthWinners.length === capturedWinners.length;
  const bidsResult: DomainAuditResult = {
    domain: 'Bids & Winning Bids',
    passed: bidsPassed,
    score: bidsPassed ? 100 : 50,
    summary: bidsPassed ? `Winning bids accounted for (${truthWinners.length} winners).` : `Winning bids mismatch: expected ${truthWinners.length}, captured ${capturedWinners.length}`,
    details: {
      expected: truthWinners,
      actual: capturedWinners,
    },
  };

  // 7. Ad Units Reconcile
  const truthAdUnits = truth.adUnits || [];
  const truthCodes = truthAdUnits.map((u: any) => u.code).filter(Boolean);
  const adUnitsPassed = truthCodes.length > 0 ? (captured.mcpSnapshot?.adUnitsCount || 0) >= truthCodes.length : true;
  const adUnitsResult: DomainAuditResult = {
    domain: 'Ad Units',
    passed: adUnitsPassed,
    score: adUnitsPassed ? 100 : 50,
    summary: adUnitsPassed ? `Ad units accounted for (${truthCodes.length} units).` : `Ad units count discrepancy`,
    details: {
      expected: truthCodes,
    },
  };

  const overallPassed = versionResult.passed && modulesResult.passed && configResult.passed && eventsResult.passed && userIdsResult.passed && bidsResult.passed && adUnitsResult.passed;

  return {
    timestamp: new Date().toISOString(),
    targetUrl,
    overallPassed,
    namespace: truth.namespace || 'pbjs',
    domains: {
      version: versionResult,
      modules: modulesResult,
      config: configResult,
      events: eventsResult,
      userIds: userIdsResult,
      bids: bidsResult,
      adUnits: adUnitsResult,
    },
  };
}

/**
 * Formats a SurfaceAuditReport into a clean Markdown table.
 */
export function formatAuditReportMarkdown(report: SurfaceAuditReport): string {
  const statusBadge = report.overallPassed ? '✅ **PASS (100% Surface Match)**' : '❌ **FAIL (Discrepancies Found)**';

  let md = `# Professor Prebid Data Surface Audit Report\n\n`;
  md += `- **URL / Target**: \`${report.targetUrl}\`\n`;
  md += `- **Timestamp**: \`${report.timestamp}\`\n`;
  md += `- **Prebid Namespace**: \`${report.namespace}\`\n`;
  md += `- **Overall Verdict**: ${statusBadge}\n\n`;

  md += `## Domain Audit Breakdown\n\n`;
  md += `| Prebid Domain | Status | Match Score | Summary |\n`;
  md += `|---|---|---|---|\n`;

  for (const [, result] of Object.entries(report.domains)) {
    const badge = result.passed ? '✅ Pass' : '❌ Fail';
    md += `| **${result.domain}** | ${badge} | ${result.score}% | ${result.summary} |\n`;
  }

  md += `\n## Detailed Discrepancy Diagnostics\n\n`;
  let hasDiscrepancies = false;
  for (const [key, result] of Object.entries(report.domains)) {
    if (!result.passed) {
      hasDiscrepancies = true;
      md += `### ⚠️ Discrepancy in ${result.domain} (\`${key}\`)\n`;
      md += `- **Summary**: ${result.summary}\n`;
      md += `\`\`\`json\n${JSON.stringify(result.details, null, 2)}\n\`\`\`\n\n`;
    }
  }

  if (!hasDiscrepancies) {
    md += `> No discrepancies detected. All Prebid runtime configurations, event streams, user IDs, and auction metrics are 100% captured and available to the Professor Prebid extension panels.\n`;
  }

  return md;
}
